-- Prediction Query
SELECT COUNT(DISTINCT pa.player_fifa_api_id) AS num_players FROM Player_Attributes AS pa JOIN Player AS p ON pa.player_fifa_api_id = p.player_fifa_api_id WHERE STRFTIME('%Y', p.birthday) < '1986' AND pa.defensive_work_rate = 'high';

/*
Prediction Result:
(1,)
